      FROM "Restaurant"
      WHERE "ResID" < arg1
        AND "ResName" LIKE arg2
    ) LOOP
      /* A row that is successfully read is counted before its processing */
      v_row_count := v_row_count + 1;

      IF r.resid > 25 THEN
        UPDATE "Restaurant"
           SET "ResName" = 'PROMOTED'
         WHERE "ResID" = r.resid
           AND "ResName" = r.resname;

      ELSIF r.address = arg3 THEN
        SELECT COUNT(*)
          INTO v_cnt
          FROM "Visits_Restaurant" vr
          JOIN "Student" s
            ON s."StuID" = vr."StuID"
         WHERE vr."ResID" = r.resid
           AND s."LName" = arg5;

        IF v_cnt > 0 THEN
          UPDATE "Restaurant"
             SET "Address" = 'RETAINED'
           WHERE "ResID" = r.resid
             AND "ResName" = r.resname;
        ELSE
          DELETE FROM "Restaurant"
           WHERE "ResID" = r.resid
             AND "ResName" = r.resname;

          DELETE FROM "Visits_Restaurant"
           WHERE "ResID" = r.resid;

          DELETE FROM "Type_Of_Restaurant"
           WHERE "ResID" = r.resid;
        END IF;

      ELSE
        UPDATE "Restaurant"
           SET "Address" = 'PENDING'
         WHERE "ResID" = r.resid
           AND "ResName" = r.resname;

        /* Rating is set only after Address has been set to 'PENDING' */
        UPDATE "Restaurant"
           SET "Rating" = arg6
         WHERE "ResID" = r.resid
           AND "ResName" = r.resname
           AND "Address" = 'PENDING';
      END IF;

      /* After a row is processed, adjust batch size */
      IF v_row_count >= v_batch_size THEN
        v_batch_size := v_batch_size + 5;
      END IF;
    END LOOP;

